SELECT CAST(COUNT(CASE WHEN p.dod IS NOT NULL THEN 1 END) AS FLOAT) / NULLIF(COUNT(p.subject_id), 0) AS mortality_rate, p.hadm_id, p.dischtime - p.admittime AS los, d.discharge_location FROM patients p JOIN admissions a ON p.subject_id = a.subject_id AND p.hadm_id = a.hadm_id JOIN icustays i ON a.subject_id = i.subject_id AND a.hadm_id = i.hadm_id JOIN discharges d ON a.subject_id = d.subject_id AND a.hadm_id = d.hadm_id WHERE p.gender = 'M' AND p.anchor_age = 74 AND p.anchor_year = 2017 AND p.anchor_year_group = 'AMI' AND p.subject_id IN (SELECT subject_id FROM patients WHERE gender = 'M' AND EXTRACT(YEAR FROM age(CURRENT_DATE, dod)) BETWEEN 69 AND 79) AND (d.cause_death IS NULL OR d.cause_death NOT IN ('Shock', 'Respiratory failure')) AND (i.length_of_stay <= 3 OR (i.length_of_stay > 3 AND i.length_of_stay <= 7)) GROUP BY p.hadm_id, p.dischtime - p.admittime ORDER BY p.hadm_id NULLS LAST;